/**
 * SF Symbols exported from Marcus's Figma sidebar (TrDfmQjPQHd1pcsYhESjuN, node 21:1129).
 * They fill their box edge to edge (Lucide icons leave ~2px padding), so a 14px symbol reads
 * like a 16px Lucide icon. Paths paint in currentColor.
 */
type SymbolProps = Omit<SVGProps<SVGSVGElement>, "viewBox" | "children">;

function makeSymbol(viewBox: string, paths: ReadonlyArray<string>, displayName: string) {
  function SfSymbol({ className, ...props }: SymbolProps) {
    return (
      <svg
        aria-hidden="true"
        fill="currentColor"
        viewBox={viewBox}
        className={cn("size-icon shrink-0", className)}
        {...props}
      >
        {paths.map((d) => (
          <path key={d.slice(0, 24)} d={d} />
        ))}
      </svg>
    );
  }
  SfSymbol.displayName = displayName;
  return SfSymbol;
}

